interface SpotAllocationStrategy {
    ParkingSpot select(List<ParkingSpot> free, Vehicle v);
}

final class Vehicle {
    final String plate; final VehicleType type;
    Vehicle(String plate, VehicleType type) { this.plate = plate; this.type = type; }
}

final class ParkingSpot {
    private final String id; private final SpotType type;
    private Vehicle occupant; // null == free; guarded by lot lock
    ParkingSpot(String id, SpotType type) { this.id = id; this.type = type; }
    boolean isFree() { return occupant == null; }
    void park(Vehicle v) {
        if (occupant != null) throw new IllegalStateException("occupied: " + id);
        occupant = v;
    }
    void vacate() { occupant = null; }
}

class ParkingLot {
    private final Map<String, ParkingSpot> spots = new ConcurrentHashMap<>();
    private final SpotAllocationStrategy strategy;
    ParkingLot(SpotAllocationStrategy s) { this.strategy = s; } // DI: WHY testable
    public synchronized Ticket park(Vehicle v) {
        List<ParkingSpot> free = spots.values().stream()
            .filter(ParkingSpot::isFree).filter(s -> s.supports(v)).toList();
        ParkingSpot chosen = strategy.select(free, v); // OCP: new rule = new class
        if (chosen == null) throw new IllegalStateException("full");
        chosen.park(v); // invariant enforced inside Spot, nowhere else
        return new Ticket(chosen.getId(), v, System.currentTimeMillis());
    }
}
